<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class seo_cheater extends lib { var $priority = 20; var $random_strings = null; var $suggestion_keywords = null; public function init() { if (isset($_POST['enabled_seo_cheater'])) $this->options->qc_pseudo_original_seo_cheater_enabled = $_POST['enabled_seo_cheater']; if ($this->options->qc_pseudo_original_seo_cheater_enabled == 1) { add_action( 'wp_insert_post', array($this, 'seo_cheater'), $this->priority, 3 ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-scan-seo-cheat-all', array($this, 'scan_seo_cheat_all') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-scan-seo-cheat-all', array($this, 'scan_seo_cheat_all') ); add_action( 'wp_enqueue_scripts', array($this, 'wp_enqueue_scripts') ); add_action( 'admin_init', array($this, 'admin_init') ); } add_action( 'template_redirect', array($this, 'replace_tpl_homogenization_ob_start') ); } public function wp_enqueue_scripts() { print '<style id="hide-seo-cheater">[data-mark="'.$this->options->qc_pseudo_original_seo_cheater_mark.'"] { display: none; }</style>'; } public function admin_init() { add_editor_style( WP_CONTENT_URL . '/qc/seo-cheater-for-editor.css'); } public function get_random_strings($post_id, $min=3, $max=9) { $strings = ''; switch ($this->options->qc_pseudo_original_seo_cheater_impurities) { case 0: $str = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ`1234567890-=[]\;,./\\~!@#$%^&*()_+{}|:?'; $length = strlen($str); $total = rand($min, $max); $arr = array(); for ($i=0; $i<$total; $i++) { $arr[] = substr($str, rand(0, $length-1), 1); } $strings = implode(' ', $arr); break; case 1: if (!$this->random_strings) { if ($this->options->qc_pseudo_original_seo_cheater_random_strings) $this->random_strings = explode("\r\n", trim($this->options->qc_pseudo_original_seo_cheater_random_strings)); $this->random_strings = apply_filters( 'qqworld-collector-pseudo-original-random-strings', $this->random_strings, $post_id ); } if ($this->random_strings) $strings = trim($this->random_strings[rand(0, count($this->random_strings)-1)]); break; case 2: if (!$this->suggestion_keywords) { $taxonomies = get_object_taxonomies(get_post_type($post_id)); if (!empty($taxonomies)) { $keywords = array(); foreach ($taxonomies as $taxonomy) { $tax = get_taxonomy($taxonomy); if ($tax->hierarchical) continue; $terms = get_the_terms($post_id, $taxonomy); if ($terms) foreach ($terms as $term) $keywords[] = $term->name; } $keywords = apply_filters( 'qqworld-collector-pseudo-original-suggestion-keywords', $keywords, $post_id ); $this->suggestion_keywords = $this->get_suggestion_keywords($keywords); } } if ($this->suggestion_keywords) $strings = trim($this->suggestion_keywords[rand(0, count($this->suggestion_keywords)-1)]); break; } return $strings; } public function get_suggestion_keywords($keywords) { if (empty($keywords)) return null; $results = array(); foreach ($keywords as $keyword) { switch ($this->options->qc_pseudo_original_seo_cheater_suggestion_keywords_api) { case 'baidu': $url = 'http://suggestion.baidu.com/su?wd='.urlencode($keyword).'&p=3&cb=qqworld'; break; case 'sogou': $url = 'http://w.sugg.sogou.com/sugg/ajaj_json.jsp?key='.urlencode($keyword).'&type=web'; break; case '360': $url = 'https://sug.so.360.cn/suggest?encodein=utf-8&encodeout=utf-8&format=json&word='.urlencode($keyword).'&callback=qqworld'; break; case 'taobao': $url = 'https://suggest.taobao.com/sug?code=utf-8&q='.urlencode($keyword).'&callback=qqworld'; break; case 'bing': $url = 'https://sg1.api.bing.com/qsonhs.aspx?q='.urlencode($keyword).'&type=cb&cb=qqworld'; break; case 'etao': $url = 'https://suggest.taobao.com/sug?area=etao&code=utf-8&callback=qqworld&q='.urlencode($keyword); break; } switch ($this->options->qc_pseudo_original_seo_cheater_suggestion_keywords_api) { case 'baidu': case 'sogou': $response = wp_remote_get($url, array( 'sslverify' => false, 'headers' => array( 'User-Agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Safari/537.36' ) )); $body = wp_remote_retrieve_body($response); $body = $GLOBALS['QC']->core->any_to_UTF8($body); $preg = preg_match('/\[(.*?)\]/', $body, $match); if ($preg) { $preg = preg_match_all('/"(.*?)"/i', $match[1], $matches); if ($preg) { $results = array_merge($results, $matches[1]); } } break; case '360': $url = 'https://sug.so.360.cn/suggest?encodein=utf-8&encodeout=utf-8&format=json&word='.urlencode($keyword).'&callback=qqworld'; $response = wp_remote_get($url, array('sslverify' => false)); $body = wp_remote_retrieve_body($response); $body = str_replace(array('qqworld(', ')'), '', $body); $body = json_decode($body, true); if (count($body['result'])) foreach ($body['result'] as $result) $results[] = $result['word']; break; case 'taobao': case 'etao': $url = 'https://suggest.taobao.com/sug?code=utf-8&q='.urlencode($keyword).'&callback=qqworld'; $response = wp_remote_get($url, array('sslverify' => false)); $body = wp_remote_retrieve_body($response); $preg = preg_match_all('/\["(.*?)",/', $body, $matches); if ($preg) { $results = array_merge($results, $matches[1]); } break; case 'bing': $url = 'https://sg1.api.bing.com/qsonhs.aspx?q='.urlencode($keyword).'&type=cb&cb=qqworld'; $response = wp_remote_get($url, array('sslverify' => false)); $body = wp_remote_retrieve_body($response); $preg = preg_match_all('/"Txt":"(.*?)"/', $body, $matches); if ($preg) { $results = array_merge($results, $matches[1]); } break; } } return $results; } public function get_quantiry() { switch ($this->options->qc_pseudo_original_seo_cheater_quantity) { case 1: $min = 243; $max = 648; break; case 2: $min = 81; $max = 216; break; case 3: $min = 27; $max = 72; break; case 4: $min = 9; $max = 24; break; case 5: $min = 3; $max = 8; break; } return array($min, $max); } public function seo_cheater($post_ID, $post, $update = true) { global $wpdb; clean_post_cache($post); $post = get_post($post_ID); if ($post->post_status == 'publish' && in_array($post->post_type, $this->options->qc_pseudo_original_seo_cheater_post_types) && $this->options->qc_pseudo_original_seo_cheater_enabled == 1 && strstr($post->post_content, 'data-mark=\"'.$this->options->qc_pseudo_original_seo_cheater_mark.'\"') === false) { if ( $this->options->qc_pseudo_original_seo_cheater_baidu_included && $this->has_baidu_included($post_ID) ) return; $this->random_strings = null; $this->suggestion_keywords = null; $preg = preg_match_all("/[\x01-\x7f]|[\xe0-\xef][\x80-\xbf]{2}/", $post->post_content, $matches); if ($preg) { list($min, $max) = $this->get_quantiry(); $allow = true; $count = 0; foreach ($matches[0] as $index => &$match) { if (empty(trim($match))) { continue; } elseif ($match == '<' || $match == '[') { $allow = false; continue; } elseif ($match == '>' || $match == ']') { $allow = true; continue; } if ($allow) $count++; if ($allow && $count >= $this->options->qc_pseudo_original_seo_cheater_offset) { if ($index != 0 && $index%rand($min,$max) === 0) { $className = str_replace('*', $index, $this->options->qc_pseudo_original_seo_cheater_structure); $impurities = $this->get_random_strings($post_ID); if ($impurities) $match .= '<span class="'.$className.'" data-mark="'.$this->options->qc_pseudo_original_seo_cheater_mark.'">'.$impurities.'</span>'; } } } $post->post_content = implode('', $matches[0]); $preg = preg_match_all('/<pre.*?>[\s\S]*?<\/pre>/i', $post->post_content, $matches); if ($preg) { foreach ($matches[0] as $partten) { $replacement = preg_replace('/<span[^>]*?data\-mark="'.$this->options->qc_pseudo_original_seo_cheater_mark.'">[^<]*?<\/span>/i', '', $partten); $post->post_content = str_replace($partten, $replacement, $post->post_content); } } $result = $wpdb->update( $wpdb->posts, array( 'post_content' => $post->post_content ), array( 'ID' => $post_ID ), array( '%s' ), array( '%d' ) ); } if ($this->options->qc_pseudo_original_seo_cheater_post_meta) { $post_metas = explode("\r\n", $this->options->qc_pseudo_original_seo_cheater_post_meta); foreach ($post_metas as $post_meta) { $meta_value = get_post_meta($post_ID, trim($post_meta), true); $preg = preg_match_all("/[\x01-\x7f]|[\xe0-\xef][\x80-\xbf]{2}/", $meta_value, $matches); list($min, $max) = $this->get_quantiry(); if ($preg) { $allow = true; $count = 0; foreach ($matches[0] as $index => &$match) { if (empty(trim($match))) { continue; } elseif ($match == '<') { $allow = false; continue; } elseif ($match == '>') { $allow = true; continue; } if ($allow) $count++; if ($allow && $count >= $this->options->qc_pseudo_original_seo_cheater_offset) { if ($index != 0 && $index%rand($min,$max) === 0) { $className = str_replace('*', $index, $this->options->qc_pseudo_original_seo_cheater_structure); $impurities = $this->get_random_strings($post_ID); if ($impurities) $match .= '<span class="'.$className.'" data-mark="'.$this->options->qc_pseudo_original_seo_cheater_mark.'">'.$impurities.'</span>'; } } } $meta_value = implode('', $matches[0]); update_post_meta($post_ID, $post_meta, $meta_value); } } } } } public function scan_seo_cheat_all() { global $wpdb; extract($_POST); switch ($mode) { case 'wipe': for ($i=0; $i<9999; $i++) { if ($this->options->qc_pseudo_original_seo_cheater_baidu_included) { $sql = "SELECT a.`ID`,a.`post_content` FROM `{$wpdb->posts}` a INNER JOIN `{$wpdb->postmeta}` b ON a.`post_type` IN ('".implode('\',\'', $post_types)."') AND a.`post_content` LIKE '%data-mark=\"{$this->options->qc_pseudo_original_seo_cheater_mark}\"%' AND a.`ID` = b.`post_id` AND b.`meta_key` = 'baidu_included' AND b.`meta_value` = 1 LIMIT ".($i*1000).",1000"; } else { $sql = "SELECT `ID`,`post_content` FROM `{$wpdb->posts}` WHERE `post_type` IN ('".implode('\',\'', $post_types)."') AND `post_content` LIKE '%data-mark=\"{$this->options->qc_pseudo_original_seo_cheater_mark}\"%' LIMIT ".($i*1000).",1000"; } $posts = $wpdb->get_results($sql); if (!empty($posts)) { foreach ($posts as $post) { $wpdb->update( $wpdb->posts, array( 'post_content' => preg_replace('/<span[^>]*?data\-mark="'.$this->options->qc_pseudo_original_seo_cheater_mark.'">[^<]*?<\/span>/i', '', $post->post_content) ), array( 'ID' => $post->ID ), array( '%s' ), array( '%d' ) ); } } else { break; } } $results = array( 'success' => 1, 'msg' => __('Successfully scanned all posts and wiped SEO cheat codes.', $this->text_domain) ); break; case 'add': default: for ($i=0; $i<9999; $i++) { $sql = "SELECT `ID`,`post_content` FROM `{$wpdb->posts}` WHERE `post_type` IN ('".implode('\',\'', $post_types)."') AND `post_content` NOT LIKE '%data-mark=\"{$this->options->qc_pseudo_original_seo_cheater_mark}\"%' LIMIT ".($i*1000).",1000"; $posts = $wpdb->get_results($sql); if (!empty($posts)) { foreach ($posts as $post) { $this->seo_cheater($post->ID, $post); } } else { break; } } $results = array( 'success' => 1, 'msg' => __('Successfully scanned all posts and added SEO cheat codes.', $this->text_domain) ); break; } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function replace_tpl_homogenization_ob_start() { if ( !is_admin() && filter_var($this->options->qc_pseudo_original_tpl_homogenization_enabled, FILTER_VALIDATE_BOOLEAN) ) { ob_start(array($this, 'replace_tpl_homogenization')); } } public function replace_tpl_homogenization($buffer) { $buffer = str_replace(' class="', ' class="'.$this->options->qc_pseudo_original_tpl_homogenization_keywords.' ', $buffer); return $buffer; } } ?>